import test, { before } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';
import { extractMcpAppCardV4, placement, adapterExports, LINKED_AREAS } from '../scripts/extract-mcp-app-card-v4.mjs';
import * as official from '../scripts/official-4.16336.0.mjs';

// batch3 mcp-app-card: the 4.16336.0 MCP App / Visualize widget card (c96d752d0-D9VB6ArX ZB = w(QJe)), generated by
// scripts/extract-mcp-app-card-v4.mjs next to the 3.6556.2 card that 9 consumers still link (staged dual output). The
// tests read the generator's own check run and the files it wrote; no official code is executed except the
// import-free tool-names.mjs, and no host file is changed (the adapter patch is applied in memory).
const ROOT = path.resolve(import.meta.dirname, '..');
const LEGACY = path.join(ROOT, 'src/generated/mcp-app-card');
const REGION = path.join(ROOT, '../analysis/claude-4.16336.0-migrate-20261104/regions/batch3/mcp-app-card');
const PATCH = path.join(REGION, 'patches/source-mcp-app-card-adapters.v4.patch');
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const exists = p => fs.access(p).then(() => true, () => false);
const ROOTS = ['McpAppToolCard', 'McpAppToolCardBody', 'McpAppWidgetCard', 'mcpAppSkipReason', 'SKIP_REASON_OUTCOME',
  'isVisualizeMatch', 'stripToolServerPrefix', 'visualizeStatus', 'visualizeStatusLabel', 'truncateMiddle',
  'messageTextForComposer', 'rememberedWidgetHeight', 'COLLAPSED_WIDGET_HEIGHT', 'NO_SAFE_AREA_INSETS',
  'INLINE_DISPLAY_MODES', 'PANE_DISPLAY_MODES', 'appRendererChunk', 'LazyAppRenderer', 'AUTO_PANE_GATE', 'SERVER_HEADER_GATE'];

let run, place;
before(async () => {
  place = placement();
  run = await extractMcpAppCardV4({ check: true });
});

test('the v4 card is checked where placement puts it, on the 4.16336.0 snapshot', async () => {
  const { manifest, summary } = run;
  assert.equal(manifest.referenceVersion, '4.16336.0');
  assert.equal(manifest.referenceSnapshot, official.referenceSnapshot);
  assert.equal(summary.staged, place.staged);
  if (place.staged) assert.ok(!(await exists(path.join(ROOT, 'src/generated/mcp-app-host-v4/manifest.json'))));
  for (const m of manifest.modules) {
    assert.equal(m.referenceVersion, '4.16336.0', m.target);
    assert.equal(sha(await fs.readFile(path.join(place.output, m.target))), m.sha256, m.target);
    assert.equal(sha(await fs.readFile(path.join(official.ionSource, m.source))), m.sourceSha256, m.target);
  }
});

test('the closure is complete and holds no state another graph owns (D46 / D1 host)', () => {
  const { summary } = run;
  assert.deepEqual(summary.boundaries, []);
  assert.deepEqual(summary.problems, []);
  assert.deepEqual(summary.stateConflicts, []);
  assert.deepEqual(summary.hostStateConflicts, []);
  for (const pending of summary.d1Pending) assert.ok(pending.binding && pending.heldBy && pending.kind && pending.reachedBy, JSON.stringify(pending));
});

test('tool-card.mjs exports the 20 roots, each from the original declaration', async () => {
  const card = run.manifest.modules.find(m => m.target === 'tool-card.mjs');
  assert.equal(card.source, 'c96d752d0-D9VB6ArX.js');
  assert.deepEqual(Object.keys(card.exports).sort(), [...ROOTS].sort());
  const text = await fs.readFile(path.join(place.output, 'tool-card.mjs'), 'utf8');
  assert.match(text, /\bvar ZB = w\(QJe\);/);
  assert.match(text, /\bvar EB = 280;/);
  for (const [name, local] of Object.entries(card.exports)) assert.match(text, new RegExp(`\\b${local.replace('$', '\\$')} as ${name}\\b`));
});

test('dependencies are the v4 libraries: cds-core, mcp-app-host-v4 and the linked areas', async () => {
  const { manifest } = run;
  assert.equal(manifest.hostLibrary.area, 'mcp-app-host-v4');
  assert.deepEqual(Object.keys(manifest.linkedAreas).sort(), [...LINKED_AREAS].sort());
  const imports = manifest.modules.flatMap(m => m.imports.map(i => ({ ...i, module: m.target })));
  for (const i of imports) {
    if (i.kind === 'react' || i.kind === 'adapter') continue;
    assert.ok(!/\/mcp-app-host\/|\/routines-shared\/|\/working-line\/|\/mcp-app-card\//.test(i.from), `${i.module} links a 3.6556.2 graph: ${i.from}`);
  }
  for (const i of imports.filter(i => i.kind === 'shared-graph')) assert.ok(i.from.startsWith('../cds-core/'), i.from);
  for (const i of imports.filter(i => i.kind === 'mcp-app-host')) assert.ok(i.from.startsWith('../mcp-app-host-v4/'), i.from);
  for (const i of imports.filter(i => i.kind === 'linked-area')) assert.ok(LINKED_AREAS.some(a => i.from.startsWith(`../${a}/`)), i.from);
});

test('tool-names.mjs stays import-free and runs in plain node (E42)', async () => {
  const names = run.manifest.modules.find(m => m.target === 'tool-names.mjs');
  assert.deepEqual(names.imports, []);
  const text = await fs.readFile(path.join(place.output, 'tool-names.mjs'), 'utf8');
  assert.doesNotMatch(text, /^\s*import\b/m);
  const { mcpServerSegment } = await import(pathToFileURL(path.join(place.output, 'tool-names.mjs')).href);
  assert.equal(typeof mcpServerSegment, 'function');
});

test('the adapter patch adds exactly the names the host adapter lacks', async () => {
  const { adapterContract } = run.manifest;
  const host = await fs.readFile(path.join(ROOT, 'src/source-mcp-app-card-adapters.jsx'), 'utf8');
  const before = await adapterExports(host);
  assert.deepEqual(adapterContract.missing, adapterContract.names.filter(n => !before.has(n)));
  if (!place.staged) assert.deepEqual(adapterContract.missing, []);
  if (!(await exists(PATCH))) return;
  const patch = await fs.readFile(PATCH, 'utf8');
  const hunk = patch.slice(patch.indexOf('\n@@') + 1).split('\n').slice(1).filter(l => l !== '');
  const context = hunk.filter(l => l.startsWith(' ')).map(l => l.slice(1));
  const added = hunk.filter(l => l.startsWith('+')).map(l => l.slice(1)).join('\n');
  if (adapterContract.missing.length === 0) {
    // Applied (session-page lane): the host file ends with the patch's context followed by exactly its added lines, and
    // exports every name of the contract.
    assert.ok(host.trimEnd().endsWith(`${context.join('\n')}\n${added}`.trimEnd()), 'src/source-mcp-app-card-adapters.jsx does not end with the applied adapter patch');
    assert.deepEqual(adapterContract.names.filter(n => !before.has(n)), []);
    return;
  }
  // Not applied yet: the patch is one append hunk, its context lines must still be the end of the host file.
  assert.ok(host.trimEnd().endsWith(context.join('\n')), 'the adapter patch no longer applies to src/source-mcp-app-card-adapters.jsx');
  const patched = host + added + '\n';
  const after = await adapterExports(patched);
  assert.deepEqual(adapterContract.names.filter(n => !after.has(n)), []);
  assert.deepEqual([...after].filter(n => !before.has(n)).sort(), [...adapterContract.missing].sort());
});

test('the 3.6556.2 card its consumers link is untouched', async () => {
  const manifest = JSON.parse(await fs.readFile(path.join(LEGACY, 'manifest.json'), 'utf8'));
  assert.equal(manifest.referenceVersion, '3.6556.2');
  assert.equal(run.manifest.isolatedGraph.productionOutput, 'src/generated/mcp-app-card');
  assert.equal(run.manifest.isolatedGraph.productionVersion, '3.6556.2');
  const pins = path.join(REGION, 'before/legacy-sha256.txt');
  if (!(await exists(pins))) return;
  for (const line of (await fs.readFile(pins, 'utf8')).split('\n').filter(Boolean)) {
    const [hash, file] = line.split(/\s+/);
    assert.equal(sha(await fs.readFile(path.join(LEGACY, path.basename(file)))), hash, file);
  }
});
